def dec(s):
    return base64.b64decode("".join(s.split())).decode("utf-8")


def checked(repo, blob, what):
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as fh:
        fh.write(base64.b64decode("".join(blob.split())))
        diff = fh.name
    check = subprocess.run(["git", "apply", "--check", diff], cwd=repo, capture_output=True, text=True)
    if check.returncode:
        sys.exit(f"{what}: the change does not apply to this copy. Nothing was written.\n{check.stderr.strip()}")
    return diff


def culprits(repo):
    app = repo / "map" / "app.js"
    if "const BUNDLES = {" in app.read_text(encoding="utf-8"):
        print("culprits: already applied - nothing to do.")
        return
    hand = repo / "HANDOFF.md"
    text = hand.read_text(encoding="utf-8")
    top, keep = "\n---\n\n", "Kept as the rounds go; move a line out when it is settled.\n"
    if top not in text or keep not in text:
        sys.exit("culprits: HANDOFF.md is not laid out as expected. Nothing was written.")
    diff = checked(repo, CODE, "culprits")
    i = text.index(top) + len(top)
    text = text[:i] + dec(SECTION) + text[i:]
    j = text.index(keep) + len(keep)
    text = text[:j] + dec(RUNLIST) + text[j:]
    subprocess.run(["git", "apply", diff], cwd=repo, check=True)
    hand.write_text(text, encoding="utf-8")
    print("culprits: applied.")


def tiles_more(repo):
    if (repo / "scripts" / "aquaculture_ponds.py").exists():
        print("culprits-tiles-more: already applied - nothing to do.")
        return
    subprocess.run(["git", "apply", checked(repo, TILES, "culprits-tiles-more")], cwd=repo, check=True)
    print("culprits-tiles-more: applied.")


if __name__ == "__main__":
    if len(sys.argv) == 3 and sys.argv[1] == "--tiles":
        tiles_more(pathlib.Path(sys.argv[2]).resolve())
    elif len(sys.argv) == 1:
        culprits(pathlib.Path(__file__).resolve().parent)
    else:
        sys.exit("Run it with no arguments in culprits, or with --tiles <path> for culprits-tiles-more.")
